package es.riegocerca.maps; import android.app.Activity; import android.content.*; import android.net.Uri; import android.webkit.JavascriptInterface; import android.widget.Toast;
public class MapsBridge{private final Activity a;public MapsBridge(Activity a){this.a=a;}@JavascriptInterface public void navigate(double lat,double lon){if(!Double.isFinite(lat)||!Double.isFinite(lon)||lat<-90||lat>90||lon<-180||lon>180){a.runOnUiThread(()->Toast.makeText(a,"Coordenadas GPS no válidas",Toast.LENGTH_LONG).show());return;}a.runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_VIEW,Uri.parse("google.navigation:q="+lat+","+lon+"&mode=d"));i.setPackage("com.google.android.apps.maps");try{a.startActivity(i);}catch(ActivityNotFoundException e){try{a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.google.com/maps/dir/?api=1&destination="+lat+","+lon+"&travelmode=driving")));}catch(Exception x){Toast.makeText(a,"No se pudo abrir Google Maps",Toast.LENGTH_LONG).show();}}});}@JavascriptInterface public void openMulti(String json){a.runOnUiThread(()->{try{org.json.JSONArray arr=new org.json.JSONArray(json);if(arr.length()==0)return;int n=Math.min(arr.length(),10);String destination=arr.getString(n-1);StringBuilder url=new StringBuilder("https://www.google.com/maps/dir/?api=1&destination=").append(Uri.encode(destination)).append("&travelmode=driving");if(n>1){url.append("&waypoints=");for(int i=0;i<n-1;i++){if(i>0)url.append("%7C");url.append(Uri.encode(arr.getString(i)));}}Intent intent=new Intent(Intent.ACTION_VIEW,Uri.parse(url.toString()));intent.setPackage("com.google.android.apps.maps");try{a.startActivity(intent);}catch(ActivityNotFoundException e){intent.setPackage(null);a.startActivity(intent);}}catch(Exception e){Toast.makeText(a,"No se pudieron abrir los elementos en Google Maps",Toast.LENGTH_LONG).show();}});}}
